function initNavigation(){
 const sections=$$('main section[id]'), links=$$('.sidebar nav a');
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id)); $('#crumb').textContent=(links.find(a=>a.hash==='#'+e.target.id)?.textContent||'').trim();}}),{rootMargin:'-25% 0px -65%'}); sections.forEach(s=>io.observe(s));
 $('#menuBtn').onclick=()=>$('.sidebar').classList.toggle('open'); links.forEach(a=>a.onclick=()=>$('.sidebar').classList.remove('open'));
 $('#modeBtn').onclick=()=>{document.body.classList.toggle('detail-mode');$('#modeBtn').textContent=document.body.classList.contains('detail-mode')?'Thu gọn nội dung':'Chế độ chi tiết'};
}
function initTree(){const update=()=>{const v=+$('#flowRate').value;$('#flowRateValue').value=v+' pkt/s';$('#branchYes').classList.toggle('on',v>500);$('#branchNo').classList.toggle('on',v<=500)};$('#flowRate').oninput=update;update()}
function renderForest(kind='bagging'){$('#methodVisual').innerHTML=Array.from({length:6},(_,i)=>`<div class="tree-node" style="transition-delay:${i*.08}s">CÂY ${i+1}</div>`).join('');}
function setMethod(kind){const bag=kind==='bagging';$$('.method-tab').forEach(b=>b.classList.toggle('active',b.dataset.method===kind));$('#methodTag').textContent=bag?'RANDOM FOREST · SONG SONG':'XGBOOST · TUẦN TỰ';$('#methodTitle').textContent=bag?'Nhiều cây học độc lập rồi bỏ phiếu':'Mỗi cây mới sửa lỗi của tổng cây trước';$('#methodText').textContent=bag?'Bagging lấy nhiều mẫu bootstrap từ cùng dữ liệu. Mỗi cây học độc lập, sau đó kết quả được tổng hợp bằng bỏ phiếu hoặc trung bình.':'Boosting thêm cây theo thứ tự. Cây sau dùng gradient của lỗi để tập trung vào những phần mà tổng cây trước dự đoán chưa tốt.';$('#methodList').innerHTML=(bag?['Các cây có thể huấn luyện song song.','Giảm variance và hạn chế overfitting của một cây đơn.','Sai lầm của một cây được “pha loãng” bởi cả rừng.']:['Các cây phụ thuộc vào kết quả trước đó.','Learning rate điều khiển mức sửa của mỗi cây.','Regularization giúp tránh mô hình quá phức tạp.']).map(x=>`<li>${x}</li>`).join('');renderForest(kind);$('#runMethod').dataset.kind=kind}
function initMethods(){renderForest();$$('.method-tab').forEach(b=>b.onclick=()=>setMethod(b.dataset.method));$('#runMethod').onclick=()=>{const nodes=$$('.tree-node',$('#methodVisual'));nodes.forEach(n=>n.classList.remove('lit'));if($('#runMethod').dataset.kind==='boosting')nodes.forEach((n,i)=>setTimeout(()=>n.classList.add('lit'),i*260));else setTimeout(()=>nodes.forEach(n=>n.classList.add('lit')),100)}}
function initModelCompare(){const rf=$('#rfVotes'),xs=$('#xgbSteps');rf.innerHTML='<i></i>'.repeat(7);xs.innerHTML='<i></i>'.repeat(6);$('#compareModels').onclick=()=>{const rv=[1,1,0,1,0,1,1];$$('i',rf).forEach((e,i)=>setTimeout(()=>e.classList.toggle('attack',rv[i]),i*100));$('#rfResult').value='5/7 phiếu → Attack';const vals=[.5,.8,.6,1.1,.4,.7];$$('i',xs).forEach((e,i)=>setTimeout(()=>{e.style.transform=`scaleX(${vals[i]})`;e.style.background=i<4?'#29d3d1':'#b7f23d'},i*130));setTimeout(()=>$('#xgbResult').value='Tổng margin 4,1 → Attack',850)}}
function renderParams(model='xgb'){$('#paramControls').innerHTML=paramDefs[model].map(d=>`<div class="control"><label>${d.name}<output id="out-${d.key}">${d.value}</output></label><input data-key="${d.key}" type="range" min="${d.min}" max="${d.max}" step="${d.step}" value="${d.value}"><small>${d.desc}</small></div>`).join('');$$('#paramControls input').forEach(i=>i.oninput=()=>{$('#out-'+i.dataset.key).value=i.value;updateParamScores(model)});renderParamDict(model);updateParamScores(model)}
function updateParamScores(model){const v=Object.fromEntries($$('#paramControls input').map(i=>[i.dataset.key,+i.value]));let fit,cost,over;if(model==='xgb'){fit=40+v.depth*3+v.trees*.09+v.lr*35;over=8+v.depth*4+v.lr*70+(v.subsample===1?10:0);cost=15+v.trees*.15+v.depth*2}else{fit=35+v.depth*1.5+v.trees*.07+v.features*18;over=12+v.depth*2.3-v.leaf*2+v.features*10;cost=12+v.trees*.11+v.depth*.9}fit=Math.min(99,Math.max(5,fit));over=Math.min(99,Math.max(3,over));cost=Math.min(99,Math.max(5,cost));[['fit',fit],['overfit',over],['cost',cost]].forEach(([k,n])=>{$('#'+k+'Score').textContent=Math.round(n);$('#'+k+'Bar').style.width=n+'%'});$('#paramAdvice').innerHTML=model==='xgb'?`<b>Cách đọc:</b> depth=${v.depth} quyết định độ phức tạp mỗi cây; learning_rate=${v.lr} quyết định mỗi cây được phép sửa mạnh đến đâu. ${v.depth>10?'Độ sâu đang cao — nguy cơ học cả nhiễu tăng.':'Độ sâu đang ở vùng tương đối kiểm soát.'} ${v.lr>.15?'Learning rate lớn có thể hội tụ nhanh nhưng dễ vượt quá điểm tối ưu.':'Learning rate nhỏ cần đủ số cây để học hết tín hiệu.'}`:`<b>Cách đọc:</b> ${v.trees} cây làm kết quả bỏ phiếu ổn định hơn. max_features=${v.features} tạo mức ngẫu nhiên giữa các cây. ${v.depth>20?'Cây đang rất sâu; tăng min_samples_leaf để hạn chế lá quá đặc thù.':'Độ sâu vừa phải giúp cân bằng khả năng học và tổng quát.'}`}
function renderParamDict(model){const defs=model==='xgb'?[['gamma','Mức giảm loss tối thiểu để cho phép split mới; tăng gamma làm cây bảo thủ hơn.'],['min_child_weight','Khối lượng mẫu tối thiểu trong một node con; lớn hơn hạn chế nhánh quá đặc thù.'],['reg_lambda','Regularization L2 trên trọng số lá, làm trọng số mượt hơn.'],['reg_alpha','Regularization L1, có thể đẩy một số trọng số về 0.'],['colsample_bytree','Tỉ lệ feature lấy cho mỗi cây; hỗ trợ đa dạng và chống overfit.'],['tree_method','Cách dựng cây; hist dùng histogram để tăng tốc trên dữ liệu lớn.']]:[['bootstrap','Bật lấy mẫu có hoàn lại cho từng cây — nền tảng của bagging.'],['criterion','Hàm đo chất lượng split, thường Gini hoặc entropy/log loss.'],['class_weight','Tăng trọng số lớp hiếm khi dữ liệu mất cân bằng.'],['max_leaf_nodes','Giới hạn số lá để kiểm soát độ phức tạp.'],['min_samples_split','Số mẫu tối thiểu để một node được phép tách.'],['n_jobs','Số luồng CPU dùng để huấn luyện các cây song song.']];$('#paramDictionary').innerHTML=defs.map(([a,b])=>`<article><b>${a}</b><p>${b}</p></article>`).join('')}
function initParams(){renderParams();$$('.param-tab').forEach(b=>b.onclick=()=>{$$('.param-tab').forEach(x=>x.classList.toggle('active',x===b));renderParams(b.dataset.model)})}
function renderAttacks(group='all',term=''){const t=term.toLowerCase();const data=attackData.filter(a=>(group==='all'||a.group===group)&&(`${a.name} ${a.summary} ${a.features.join(' ')}`.toLowerCase().includes(t)));$('#attackGrid').innerHTML=data.map((a,i)=>`<article class="attack-card" data-index="${attackData.indexOf(a)}"><div class="attack-top"><span class="tag">${a.group.toUpperCase()}</span><span class="f1">F1 <b>${(a.f1*100).toFixed(1)}%</b></span></div><h3>${a.name}</h3><p>${a.summary}</p><small>${a.support.toLocaleString('vi-VN')} test flows · ${a.level}</small></article>`).join('')||'<p>Không tìm thấy attack phù hợp.</p>';$$('.attack-card').forEach(c=>c.onclick=()=>openAttack(attackData[+c.dataset.index]))}
function openAttack(a){$('#attackDetail').innerHTML=`<div class="card-label">ATTACK PROFILE · ${a.group.toUpperCase()}</div><h2>${a.name}</h2><p>${a.summary}</p><div><span class="metric-pill">F1 ${(a.f1*100).toFixed(2)}%</span><span class="metric-pill">Support ${a.support.toLocaleString('vi-VN')}</span><span class="metric-pill">${a.level}</span></div><div class="attack-detail-grid"><div><h4>Dấu hiệu mạng thường gặp</h4><ul>${a.signals.map(x=>`<li>${x}</li>`).join('')}</ul></div><div><h4>Top feature minh họa</h4><ol>${a.features.map(x=>`<li>${x}</li>`).join('')}</ol></div></div><h4>Đọc kết quả cẩn thận</h4><p>${a.note}</p>`;$('#attackDialog').showModal()}
function initAttacks(){renderAttacks();let group='all';$$('#attackFilters button').forEach(b=>b.onclick=()=>{group=b.dataset.group;$$('#attackFilters button').forEach(x=>x.classList.toggle('active',x===b));renderAttacks(group,$('#attackSearch').value)});$('#attackSearch').oninput=e=>renderAttacks(group,e.target.value);$('#closeDialog').onclick=()=>$('#attackDialog').close()}
function renderXai(){const d=xaiFlows[$('#flowSelect').value],k=+$('#kSelect').value;const s=d.shap.slice(0,k),l=d.lime.slice(0,k);const make=(arr,type)=>arr.map(([n,v,sign])=>`<div class="bar-row"><span>${n}</span><i class="bar-track"><em class="bar-fill ${type==='lime'?'lime':''} ${sign<0?'neg':''}" style="width:${Math.max(8,Math.abs(v)/(Math.max(...arr.map(x=>Math.abs(x[1]))))*100)}%"></em></i><output>${v>0?'+':''}${v}</output></div>`).join('');$('#shapBars').innerHTML=make(s,'shap');$('#limeBars').innerHTML=make(l,'lime');const sn=new Set(s.map(x=>x[0])),ln=new Set(l.map(x=>x[0])),common=[...sn].filter(x=>ln.has(x));const union=new Set([...sn,...ln]);const jac=common.length/union.size;let agree=0;common.forEach(n=>{if(s.find(x=>x[0]===n)[2]===l.find(x=>x[0]===n)[2])agree++});const sign=common.length?agree/common.length:0;$('#jaccardValue').textContent=jac.toFixed(3);$('#signValue').textContent=(sign*100).toFixed(1)+'%';$('#r2Value').textContent=d.r2.toFixed(2);$('#xaiConclusion').textContent=`Hai phương pháp trùng ${common.length}/${union.size} feature trong hợp Top-${k}. ${sign>.8?'Các feature chung phần lớn cùng hướng ảnh hưởng.':'Có bất đồng về hướng ở một số feature chung.'} ${d.r2<.1?'Local R² rất thấp: không nên dùng LIME làm bằng chứng chính cho flow này.':'Local R² ở mức dùng để tham khảo, vẫn cần thận trọng.'}`}
function initXai(){$('#flowSelect').onchange=renderXai;$('#kSelect').onchange=renderXai;renderXai()}
function initJaccard(){const A=['Dst Port','RST Flag','Bwd IAT','Flow Duration','Pkt Len'];let B=['Dst Port','RST Flag','FIN Flag','Fwd URG','IAT Min'];const render=()=>{$('#setA').innerHTML=A.map(x=>`<span>${x}</span>`).join('');$('#setB').innerHTML=B.map(x=>`<button class="${A.includes(x)?'common':''}">${x}</button>`).join('');const inter=A.filter(x=>B.includes(x)).length,union=new Set([...A,...B]).size;$('#jDemo').textContent=(inter/union).toFixed(2);$$('#setB button').forEach((b,i)=>b.onclick=()=>{B[i]=A.includes(B[i])?['FIN Flag','Fwd URG','IAT Min','CWE Flag','Header Len'].find(x=>!B.includes(x)):A.find(x=>!B.includes(x))||B[i];render()})};render();const imgs={agreement:'assets/agreement.png',signed:'assets/shap-lime-signed.png',faithfulness:'assets/faithfulness.png'};$$('[data-figure]').forEach(b=>b.onclick=()=>{$('#figureImage').src=imgs[b.dataset.figure];$('#figureDialog').showModal()});$('#closeFigure').onclick=()=>$('#figureDialog').close()}
const alerts=[
 {sev:'CRITICAL',name:'DDoS-LOIC-HTTP',src:'192.168.10.24',dst:'10.0.0.5:80',conf:99.7,proto:'TCP',time:'10:24:31',features:[['Fwd Pkts/s',92],['Fwd IAT Std',78],['FIN Flag Cnt',57],['Flow Duration',34]]},
 {sev:'HIGH',name:'SSH-Bruteforce',src:'192.168.10.31',dst:'10.0.0.8:22',conf:98.6,proto:'TCP',time:'10:25:07',features:[['Dst Port',95],['RST Flag Cnt',72],['Flow IAT Mean',61],['Flow Duration',40]]},
 {sev:'MEDIUM',name:'Bot',src:'192.168.10.19',dst:'172.16.4.9:8080',conf:87.4,proto:'TCP',time:'10:26:12',features:[['Dst Port',88],['RST Flag Cnt',70],['Bwd IAT Min',54],['FIN Flag Cnt',37]]}
];
function renderAlerts(){const root=$('#alertRows');root.innerHTML=alerts.map((a,i)=>`<div class="alert-row" data-i="${i}"><span class="severity">${a.sev}</span><div><b>${a.name}</b><small>${a.time} · ${a.src}</small></div><output>${a.conf}%</output></div>`).join('');$$('.alert-row',root).forEach(r=>r.onclick=()=>showAlert(+r.dataset.i,r))}
function showAlert(i,row){const a=alerts[i];$$('.alert-row').forEach(x=>x.classList.toggle('active',x===row));$('#investigationEmpty').hidden=true;const d=$('#investigationDetail');d.hidden=false;d.innerHTML=`<div class="investigation-content"><div class="alert-heading"><div><div class="card-label">${a.sev} · ${a.time}</div><h3>${a.name}</h3></div><div class="confidence-ring">${a.conf}%</div></div><div class="flow-meta"><div><small>SOURCE</small><b>${a.src}</b></div><div><small>DESTINATION</small><b>${a.dst}</b></div><div><small>PROTOCOL</small><b>${a.proto}</b></div></div><h4>Vì sao model cảnh báo?</h4><div class="reason-list">${a.features.map(([n,v])=>`<div><span>${n}</span><i><em style="width:${v}%"></em></i><b>+${(v/25).toFixed(1)}</b></div>`).join('')}</div><p class="demo-note">SHAP cho biết đóng góp vào dự đoán, không chứng minh nguyên nhân tấn công. Analyst cần đối chiếu log và ngữ cảnh tài sản.</p></div>`}
function initSoc(){renderAlerts();$('#runSoc').onclick=()=>{const steps=$$('#pipeline div');steps.forEach(x=>x.classList.remove('active'));steps.forEach((x,i)=>setTimeout(()=>x.classList.add('active'),i*350));setTimeout(()=>{steps.forEach(x=>x.classList.remove('active'));$('#latencyKpi').textContent='1.84 s';$('#flowKpi').textContent='131';$('#alertKpi').textContent='04';showAlert(0,$$('.alert-row')[0])},steps.length*350+200)}}
initNavigation();initTree();initMethods();initModelCompare();initParams();initAttacks();initXai();initJaccard();initSoc();
